    }

    @Test
    public void getBuildJobName_ReturnsCorrectBuildJobName() {
        String amiName = "my-ami-name-1234";
        assertEquals("1234", AppVersion.parseName(amiName).getBuildJobName());
    }

    @Test
    public void getBuildNumber_ReturnsCorrectBuildNumber() {
        String amiName = "my-ami-name-1234";
